 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Each outline is a V whose two sides run one cell diagonally per row,
    # from an apex to the opposite edge of the grid. Fill its interior with 2.
    for r0 in range(h):
        for c0 in range(w):
            color = grid[r0][c0]
            if color == 0:
                continue
            for dr in (-1, 1):
                depth = (h - 1 - r0) if dr == 1 else r0
                if depth == 0:
                    continue
                valid = True
                levels = []
                for k in range(1, depth + 1):
                    r = r0 + dr * k
                    left, right = c0 - k, c0 + k
                    if left < 0 and right >= w:
                        valid = False
                        break
                    if left >= 0 and grid[r][left] != color:
                        valid = False
                        break
                    if right < w and grid[r][right] != color:
                        valid = False
                        break
                    levels.append((r, left, right))
                if valid:
                    for r, left, right in levels:
                        for c in range(max(0, left + 1), min(w, right)):
                            if grid[r][c] == 0:
                                out[r][c] = 2
    return out
