        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            for a in cols:
                for b in cols:
                    if b <= a:
                        continue
                    # Rays can converge downward or upward. Require the
                    # interior boundary markers on every intervening row.
                    for dr in (1, -1):
                        depth = (h - 1 - r) if dr == 1 else r
                        if depth == 0 or b-a != 2*depth:
